/* Presentation and growth layer on the exported application's real domain functions. */
(()=>{
const mode=document.body.dataset.mode,child=mode==='child';
const ui={route:'today',date:todayStr(),range:'week',planType:'all',project:'garden',roomEdit:false,selectedItem:'shell',remove:false,active:null,showDone:false,legacy:null};
const projects=[{id:'garden',name:'小岛花园',cost:20,desc:'在家门前种一片花，留一张可以歇脚的长椅。'},{id:'dock',name:'海边码头',cost:30,desc:'顺着石板路走到海边，给小船留一个停靠的地方。'},{id:'library',name:'森林书屋',cost:40,desc:'在树林里，建一间属于所有伙伴的阅读小屋。'}];
const cast=Object.fromEntries(DemoCore.companions.map(m=>[m.emoji,[m.id,m.name,m.line,m.src]]));
const roomSlots=DemoCore.roomSlots;
const e=escapeHtml,attr=v=>e(String(v)).replace(/'/g,'&#39;');
const image=(name,cls='',alt='')=>`<img class="${cls}" src="assets/characters/${name==='house'?'logo_house':'icon_'+name}.png" alt="${alt}" loading="lazy" decoding="async">`;
const button=(text,action,cls='up-button',extra='')=>`<button type="button" class="${cls}" data-up="${action}" ${extra}>${text}</button>`;
let root,nav,header,ready=false;
function data(){return DemoCore.ensure(getData());}
function companion(d){const owned=d.rewardsUnlocked||['🐻'];const emo=owned.includes(d.todayMate)?d.todayMate:owned[0];const c=cast[emo];const item=(d.rewardItems||[]).find(x=>x.type==='mate'&&x.emoji===emo);return {emoji:emo,name:item?.name||c?.[1]||'我的伙伴',line:c?.[2]||'今天也和你一起加油。',src:c?c[3]:null};}
function buddy(d,cls='up-buddy'){const b=companion(d);return b.src?`<img class="${cls}" src="${b.src}" alt="${e(b.name)}" loading="lazy" decoding="async" fetchpriority="${ui.route==='today'?'high':'auto'}">`:`<span class="${cls} up-emoji-buddy" role="img" aria-label="${e(b.name)}">${e(b.name.slice(0,1))}</span>`;}
function sceneBuddy(d,kind){return `<span class="up-scene-buddy ${kind}" aria-hidden="true">${buddy(d,'up-scene-character')}</span>`;}
function companionStrip(d){const b=companion(d);return `<div class="up-companion-strip">${buddy(d)}<div><b>${e(b.name)}陪我写作业</b><small>${e(b.line)}</small></div>${button('更换伙伴','mate-picker','up-link','aria-label="选择陪写伙伴"')}</div>`;}
function matePicker(task=null){ui.mateReturnTask=task;modal(`<div class="up-eyebrow">一起写作业的小岛伙伴</div><h1>今天想和谁一起？</h1><p class="up-muted">选择已经解锁的伙伴，它会出现在作业里，陪你完成每一件事。</p>${mateCards(data(),true)}`);}
function earnedPreview(d,h){const streak=d.lastCompletedDate===todayStr()?(d.currentStreak||1):d.lastCompletedDate===DemoCore.date(-1)?(d.currentStreak||0)+1:1;return (Number(h.points)||0)+Math.min(streak*2,20);}
function dayItems(d,day=ui.date){return buildDayTimeline(d,new Date(day+'T12:00:00')).items;}
function nextProject(d){return projects.find(p=>!d.demoGrowth.buildings.includes(p.id));}
function stage(d){return projects.filter(p=>d.demoGrowth.buildings.includes(p.id)).length;}
function scene(d,cls=''){return `<img class="up-scene-image ${cls}" src="assets/island-stage-${stage(d)}.png" alt="${stage(d)===0?'等待建设的海岛':`已完成 ${stage(d)} 处建设的海岛`}" fetchpriority="${ui.route==='island'?'high':'auto'}" loading="lazy" decoding="async">`;}
function dateLabel(day){const dt=new Date(day+'T12:00:00');return `${dt.getMonth()+1} 月 ${dt.getDate()} 日 · ${['周日','周一','周二','周三','周四','周五','周六'][dt.getDay()]}`;}
function row(it){let title,sub,icon,tag='',act;if(it.kind==='homework'){let h=it.hw;title=h.content;sub=h.subject+(h.duration?' · 预计 '+h.duration+' 分钟':'');icon=(h.subject||'作').slice(0,1);tag=h.pendingApproval?'待确认':it.done?'已完成':`+${earnedPreview(data(),h)} 分`;act='task';}else if(it.kind==='class'){title=it.cls.name;sub=(it.cls.start||'')+' · '+(it.cls.place||'固定课程');icon='课';act='class';tag=it.done?'已打卡':'';}else{title=it.ev.title;sub=(it.ev.start||'时间自定')+' · '+(it.ev.owner==='child'?'自己安排的':'家长安排');icon='自';act='event';tag=it.done?'已完成':'';}return `<button type="button" class="up-row ${it.done?'is-done':''}" data-up="${act}" data-id="${attr(it.id)}"><span class="up-subject">${e(icon)}</span><span class="up-row-main"><b>${e(title)}</b><small>${e(sub)}</small></span><span class="up-row-state">${e(tag)}</span><span class="up-chevron">›</span></button>`;}
function journalCard(d){const entry=d.journalEntries.find(x=>x.date===todayStr()),mood=DemoCore.journalMoods.find(m=>m.id===entry?.mood);return `<section class="up-journal-card"><button type="button" class="up-journal-open" data-up="journal-edit"><span class="up-journal-emoji" aria-hidden="true">${mood?.emoji||'🍃'}</span><span><b>我今天的心情</b><small>${entry?e(entry.text||mood?.name||'给今天留了一个小记号'):'今天过得怎么样？留一句话，记住一件小事。'}</small></span><span aria-hidden="true">›</span></button>${button('翻翻以前的小记录 ›','journal','up-link')}</section>`;}
function journalEditor(day=todayStr(),draft=null){const d=data(),entry=d.journalEntries.find(x=>x.date===day);ui.journalDraft=draft||{day,mood:entry?.mood||'',text:entry?.text||''};const j=ui.journalDraft;modal(`<div class="up-eyebrow">${e(j.day)} · 小岛日记</div><h1>${j.day===todayStr()?'给今天留一小段':'补一段那天的小记录'}</h1><p class="up-muted">每一种心情都可以被记住，只选心情或写几句话都可以。</p><div class="up-moods" role="group" aria-label="今天的心情">${DemoCore.journalMoods.map(m=>button(`<span aria-hidden="true">${m.emoji}</span><small>${m.name}</small>`,'journal-mood','up-mood',`data-mood="${m.id}" aria-pressed="${j.mood===m.id}" aria-label="${m.name}"`)).join('')}</div><label class="up-journal-label" for="up-journal-text">想记住的小事<span>（可选）</span></label><textarea id="up-journal-text" class="up-journal-text" rows="4" maxlength="500" placeholder="比如：今天和朋友一起玩了，或者有一点小烦恼……">${e(j.text)}</textarea><div class="up-journal-count"><span id="up-journal-count">${j.text.length}</span> / 500 字</div><p id="up-journal-error" class="up-journal-error" role="status"></p>${button('保存这段小记录','journal-save','up-primary')}${button('翻翻以前的小记录','journal','up-link')}`);}
function journal(d){const entries=[...d.journalEntries].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="up-eyebrow">不只有作业，也记住自己的每一天</div><div class="up-heading"><h1>小岛日记</h1>${button('写今天','journal-edit','up-chip')}</div><p class="up-muted">${entries.length?'已经留下 '+entries.length+' 天的小记忆。':'开心、平静，或一点小烦恼，都可以写在这里。'}</p><div class="up-journal-history">${entries.map(j=>{const m=DemoCore.journalMoods.find(x=>x.id===j.mood);return `<article class="up-journal-entry"><div class="up-heading"><time datetime="${attr(j.date)}">${e(j.date)}${m?' · '+m.emoji+' '+m.name:''}</time>${button('编辑','journal-edit','up-link',`data-date="${attr(j.date)}" aria-label="编辑 ${attr(j.date)} 的记录"`)}</div>${j.text?`<p>${e(j.text)}</p>`:'<p class="up-muted">给这一天留了一个心情小记号。</p>'}</article>`;}).join('')||`<div class="up-empty"><h2>这一页，等你写下第一句话。</h2>${button('记下今天的心情','journal-edit','up-primary')}</div>`}</div>${d.kidMood?`<div class="up-project"><small>以前的心情签名 · 已保留</small><p class="up-journal-old">${e(d.kidMood)}</p></div>`:''}${button('回到今天','today','up-secondary')}`;}
function section(title,right=''){return `<div class="up-section"><h2>${title}</h2>${right}</div>`;}
function today(d){
 const items=dayItems(d,todayStr()),done=items.filter(x=>x.done),open=items.filter(x=>!x.done),next=items.find(x=>x.kind==='homework'&&!x.done&&!x.hw.pendingApproval),unread=(d.homework||[]).find(h=>h.rewardUnseen&&h.done);
 const head=`<div class="up-eyebrow">${dateLabel(todayStr())}</div><h1>${child?'慢慢来，一件一件做。':'今天，一起轻松一点。'}</h1><p class="up-muted">${child?'今天已完成':(d.kidName||'孩子')+'的今日进度 · 已完成'} ${done.length} / ${items.length} 件</p>${unread&&child?button('✦ 家长确认了作业，看看这次收获 ›','receipt','up-notice',`data-id="${attr(unread.id)}"`):''}<div class="up-progress" aria-label="已完成 ${done.length} 件，共 ${items.length} 件">${items.map((_,i)=>`<i class="${i<done.length?'filled':''}"></i>`).join('')}</div>`;
 if(!child)return `${head}<div class="up-parent-actions">${button('＋ 发布作业','publish','up-primary')}${button('截图／文字录入','ocr','up-secondary')}</div><div class="up-inbox">${section('需要你看一看')}${(d.homework||[]).filter(h=>h.pendingApproval).map(h=>row({kind:'homework',id:h.id,hw:h,done:false})).join('')}${(d.redemptions||[]).filter(r=>!r.fulfilled&&r.type==='prize').map(r=>`<div class="up-row"><span class="up-subject">礼</span><span class="up-row-main"><b>${e(r.name)}</b><small>孩子期待和你约个时间</small></span>${button('记录兑现','fulfill','up-chip',`data-id="${attr(r.id)}"`)}</div>`).join('')||''}${!(d.homework||[]).some(h=>h.pendingApproval)&&!(d.redemptions||[]).some(r=>!r.fulfilled&&r.type==='prize')?'<p class="up-muted">暂时没有待处理的事，孩子可以按自己的节奏继续。</p>':''}</div>${section('今日安排',button('查看计划 ›','plan','up-link'))}${open.map(row).join('')||'<p class="up-empty-line">今天暂时没有待办。</p>'}${done.length?`<details class="up-done"><summary>已完成 ${done.length} 件</summary>${done.map(row).join('')}</details>`:''}${button('＋ 添加课程或日程','add-menu','up-add')}`;
 const homework=`${next?`<div class="up-focus"><div class="up-focus-label">${image('sprout')} 接下来做</div><h2>${e(next.hw.content)}</h2><p>${e(next.hw.subject)} · ${next.hw.duration||20} 分钟左右 · +${earnedPreview(d,next.hw)} 积分</p>${button((ui.active===next.id?'继续这件事':'开始这件事')+' <span>→</span>','task','up-primary',`data-id="${attr(next.id)}"`)}</div>`:`<div class="up-focus up-focus-clear"><h2>${open.some(x=>x.hw?.pendingApproval)?'作业已提交，等家长看一看。':items.length?'今天的努力，已经留下了。':'今天还没有安排。'}</h2><p>${items.length?'留一点时间给自己，也去看看小岛吧。':'可以给自己安排一件喜欢的事。'}</p></div>`}${section('今天剩下的事',button('查看计划 ›','plan','up-link'))}${open.filter(x=>x.id!==next?.id).map(row).join('')||'<p class="up-empty-line">暂时没有其他待办。</p>'}${done.length?`<details class="up-done"><summary>已完成 ${done.length} 件</summary>${done.map(row).join('')}</details>`:''}${button('＋ 添加自己想做的事','add-menu','up-add')}`;
 return `${head}${journalCard(d)}<section class="up-today-companion"><div class="up-companion-strip">${buddy(d)}<div><b>选一个角色陪我写作业</b><small>现在由${e(companion(d).name)}陪你 · ${e(companion(d).line)}</small></div>${button('选择角色','mate-picker','up-link','aria-label="选择陪写角色"')}</div></section><section class="up-homework-zone">${section('作业区')}${homework}</section>`;
}
function plan(d){let anchor=new Date(ui.date+'T12:00:00'),dates=[];if(ui.range==='month'){const y=anchor.getFullYear(),m=anchor.getMonth();for(let i=1;i<=new Date(y,m+1,0).getDate();i++)dates.push(`${y}-${String(m+1).padStart(2,'0')}-${String(i).padStart(2,'0')}`);}else{const start=new Date(anchor);start.setDate(start.getDate()-((start.getDay()+6)%7));for(let i=0;i<7;i++){let x=new Date(start);x.setDate(x.getDate()+i);dates.push(`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`);}}
let items=dayItems(d).filter(x=>ui.planType==='all'||x.kind===ui.planType);return `<div class="up-eyebrow">${child?'给未来留一点期待':'一起把生活安排好'}</div><div class="up-heading"><h1>${child?'我的计划':'安排'}</h1>${button(ui.range==='month'?'周视图':'月视图','range','up-link')}</div><div class="up-date-nav">${button('‹','prev','up-icon-button','aria-label="上一个区间"')}<b>${anchor.getFullYear()} 年 ${anchor.getMonth()+1} 月</b>${button('›','next','up-icon-button','aria-label="下一个区间"')}</div><div class="up-weekdays">${['一','二','三','四','五','六','日'].map(x=>`<span>${x}</span>`).join('')}</div><div class="up-calendar ${ui.range==='month'?'monthly':''}">${ui.range==='month'?'<span></span>'.repeat((new Date(anchor.getFullYear(),anchor.getMonth(),1).getDay()+6)%7):''}${dates.map(day=>`<button class="up-day ${ui.date===day?'selected':''}" data-up="day" data-date="${day}" aria-pressed="${ui.date===day}"><span>${+day.slice(-2)}</span><small>${dayItems(d,day).length?'·':' '}</small></button>`).join('')}</div><div class="up-section"><h2>${dateLabel(ui.date)}</h2>${button('回今天','reset-day','up-link')}</div><div class="up-filters">${[['all','全部'],['homework','作业'],['class','课程'],['event','日程']].map(([id,label])=>button(label,'filter','up-filter',`data-filter="${id}" aria-pressed="${ui.planType===id}"`)).join('')}</div>${items.map(row).join('')||'<div class="up-empty"><h2>这一天，还是空白的。</h2><p>给它安排一点值得期待的事吧。</p></div>'}${button('＋ '+(child?'添加一件事':'添加安排'),'add-menu','up-add')}${!child?`<div class="up-settings-links">${button('管理周期作业','recurring','up-secondary')}${button('管理固定课表','classes','up-secondary')}${button('智能录入作业','ocr','up-secondary')}</div>`:button('学习回顾与报告 ›','report','up-secondary')}`;}
function islandTabs(active){return `<div class="up-tabs" aria-label="小岛空间">${[['island','建设'],['mates','伙伴'],['room','房间']].map(([id,n])=>button(n,id,'up-tab',`aria-pressed="${active===id}"`)).join('')}</div>`;}
function island(d){const p=projects.find(x=>x.id===ui.project)||nextProject(d)||projects[0],built=d.demoGrowth.buildings.includes(p.id),next=nextProject(d),eligible=next?.id===p.id;return `<div class="up-eyebrow">你的努力，正在变成一座小岛</div><div class="up-heading"><h1>我的小岛</h1><span class="up-balance">✦ ${d.points} 积分</span></div>${islandTabs('island')}<div class="up-island-scene">${scene(d)}${sceneBuddy(d,'island')}<button class="up-hotspot house" data-up="room" aria-label="进入我的小屋">我的小屋 ›</button><button class="up-hotspot garden" data-up="project" data-project="garden">小岛花园 ${d.demoGrowth.buildings.includes('garden')?'✓':''}</button><button class="up-hotspot dock" data-up="project" data-project="dock">海边码头 ${d.demoGrowth.buildings.includes('dock')?'✓':''}</button><button class="up-hotspot library" data-up="project" data-project="library">森林书屋 ${d.demoGrowth.buildings.includes('library')?'✓':''}</button></div><p class="up-scene-caption">先种一片花，再沿着小路，慢慢建设自己的家园。</p><div class="up-project"><div class="up-heading"><h2>${e(p.name)}</h2><small>${built?'已经建好':p.cost+' 建设力'}</small></div><p>${e(p.desc)}</p>${built?'<div class="up-built">✓ 已成为小岛的一部分</div>':`<div class="up-meter-label"><span>现有建设力</span><span>${d.demoGrowth.construction} / ${p.cost}</span></div><div class="up-track"><i style="width:${Math.min(100,d.demoGrowth.construction/p.cost*100)}%"></i></div>${!eligible?button('先把'+(next?.name||'前一处建设')+'建好','next-project','up-secondary'):!DemoCore.homeworkProgress(d).complete?button('先完成今日作业，再建设','continue-homework','up-primary'):d.demoGrowth.construction>=p.cost?button('开始建设 '+p.name,'build','up-primary',`data-project="${p.id}"`):button('去完成作业 · 再积累 '+(p.cost-d.demoGrowth.construction)+' 建设力','today','up-primary')}`}</div><p class="up-note">每份作业首次完成增加 10 建设力。建设不消耗积分或已经收集的宝贝。</p><div class="up-settings-links">${button('收藏图鉴与成长足迹','achieve','up-secondary')}${button('和家人的奖励约定','shop','up-secondary')}${button('学习回顾','report','up-secondary')}</div>`;}
function mateCards(d,picker=false){const b=companion(d),owned=d.rewardsUnlocked||[];return `<div class="up-mate-grid">${(d.rewardItems||[]).filter(x=>x.type==='mate'&&(x.active!==false||owned.includes(x.emoji))).map(m=>{const c=cast[m.emoji],has=owned.includes(m.emoji),active=b.emoji===m.emoji;return `<div class="up-mate-card">${c?`<img src="${c[3]}" alt="${e(m.name)}" loading="lazy">`:`<span class="up-mate-fallback" role="img" aria-label="${e(m.name)}">${e(m.name.slice(0,1))}</span>`}<h2>${e(m.name)}</h2><small>${has?'已经是岛上的伙伴':m.points+' 积分解锁'}</small>${button(active?'正在陪伴':has?'请来陪伴':'解锁伙伴',has?'choose-mate':'redeem','up-secondary',`data-id="${attr(m.id)}" ${picker?'data-picker="true"':''} ${active?'disabled':''}`)}</div>`;}).join('')}</div>`;}
function mates(d){const b=companion(d);return `<div class="up-eyebrow">写作业的时候，也有人陪伴</div><div class="up-heading"><h1>小岛伙伴</h1><span class="up-balance">${d.points} 积分</span></div>${islandTabs('mates')}<div class="up-companion-intro">${buddy(d)}<div><h2>${e(b.name)}正在陪你</h2><p>${e(b.line)}</p>${button('和我去写作业','continue-homework','up-link')}</div></div>${mateCards(d)}<p class="up-note">10 位小岛伙伴都有自己的形象。用作业积分解锁，在这里或作业页选择今天的陪写伙伴。</p>`;}
function materialArt(id){const m=MATERIALS.find(x=>x.id===id);const assets={wood:'sign',stone:'star',branch:'sprout',leaf:'leaf',flower:'butterfly',shell:'boat',fish:'fish',clownfish:'fish'};if(['wood','stone','shell','flower'].includes(id))return `<span class="up-object-emoji">${e(m?.emoji||'★')}</span>`;return assets[id]?image(assets[id],'up-object-image'): `<span class="up-object-emoji">${e(m?.emoji||'★')}</span>`;}
function room(d){const g=d.demoGrowth,unlocked=DemoCore.homeworkProgress(d).complete;if(!unlocked)ui.roomEdit=false;const zone=ui.roomZone||'shelf',action=ui.roomAction||'place',visible=roomSlots.filter(s=>s.zone===zone),allUsed=Object.keys(g.room).length;return `<div class="up-eyebrow">把每次小惊喜，摆进自己的家</div><div class="up-heading"><h1>我的房间</h1>${button(unlocked?(ui.roomEdit?'完成布置':'布置房间'):'完成作业后再布置',unlocked?'room-edit':'continue-homework','up-chip')}</div>${islandTabs('room')}<div class="up-room-scene"><img class="up-room-bg" src="assets/room.png" alt="有三层展示架、书桌与窗边的温暖小屋" decoding="async" fetchpriority="high">${sceneBuddy(d,'room')}${roomSlots.map(s=>{const id=g.room[s.id],editing=ui.roomEdit&&s.zone===zone;return `<button class="up-room-slot ${id?'occupied':''} ${editing?'editing':''} ${ui.roomFrom===s.id?'moving':''}" style="--slot-x:${s.x}%;--slot-y:${s.y}%" data-up="room-slot" data-slot="${s.id}" aria-label="${s.name}，${id?(MATERIALS.find(m=>m.id===id)?.name||id):'空位'}" ${editing?'':'disabled'}>${id?materialArt(id):editing?'<span>＋</span>':''}</button>`;}).join('')}</div>${ui.roomEdit?`<div class="up-room-zones" aria-label="布置区域">${[['shelf','展示架',12],['desk','书桌',2],['window','窗边',1]].map(([id,name,total])=>button(name+' '+roomSlots.filter(s=>s.zone===id&&g.room[s.id]).length+'/'+total,'room-zone','up-filter',`data-zone="${id}" aria-pressed="${zone===id}"`)).join('')}</div><div class="up-room-tools">${[['place','摆放收藏'],['move','移动摆件'],['remove','收回摆件']].map(([id,name])=>button(name,'room-action','up-filter',`data-action="${id}" aria-pressed="${action===id}"`)).join('')}</div><p class="up-note">${action==='move'?(ui.roomFrom?'再点一个位置，移过去；已有物品时会交换位置。':'先点一件已摆好的收藏，再选新位置。'):action==='remove'?'点一下已摆放的物品，就能收回收藏。':'先选下方收藏，再点位置；替换后，原物品会自动收回。'}</p><div class="up-room-grid">${visible.map(s=>{const id=g.room[s.id];return button(`${id?materialArt(id):'<span class="up-position-plus">＋</span>'}<small>${s.zone==='shelf'?s.name.replace('展示架第 ','').replace(' 层 · ','层 · '):s.name}</small>`,'room-slot','up-room-place',`data-slot="${s.id}" aria-label="布置${s.name}，${id?(MATERIALS.find(m=>m.id===id)?.name||id):'空位'}" aria-pressed="${ui.roomFrom===s.id}"`);}).join('')}</div>${section('我的收藏')}<div class="up-inventory">${Object.entries(d.materials||{}).filter(([,n])=>n>0).map(([id,n])=>{const used=DemoCore.roomUsage(d,id);return `<button data-up="item" data-item="${attr(id)}" class="up-inventory-item" aria-pressed="${ui.selectedItem===id&&action==='place'}">${materialArt(id)}<span>${e(MATERIALS.find(m=>m.id===id)?.name||id)}</span><small>拥有 ${n} · 已摆 ${used}</small><small>可摆 ${Math.max(0,n-used)} 件</small></button>`;}).join('')||'<p class="up-muted">完成作业后，发现的小宝贝会出现在这里。</p>'}</div>`:`<p class="up-scene-caption">${e(companion(d).name)}陪你，让这里一点一点变成自己的样子。</p><div class="up-project"><h2>小小收藏，也能摆满一面墙。</h2><p>展示架 3 层、12 个位置，另有 2 处书桌和 1 处窗边。已摆 ${allUsed} / 15 件；摆放不消耗收藏，已有摆件都保留。</p>${button(unlocked?'开始布置我的房间':'先完成今日作业，再布置',unlocked?'room-edit':'continue-homework','up-primary')}</div>`}`;}
function openKidNameEditor(d){modal(`<div class="up-eyebrow">家庭资料</div><h1>编辑孩子姓名</h1><p class="up-muted">这个名字会显示在家庭页和进度提示中。</p><label class="up-field"><span>儿童名字</span><input id="up-kid-name" type="text" maxlength="12" autocomplete="off" value="${attr(d.kidName||'')}" placeholder="输入孩子名字"></label>${button('保存姓名','save-kid-name','up-primary')}`);}
function family(d){return `<div class="up-eyebrow">陪伴，也有自己的节奏</div><h1>${child?'我的资料':'我们的家庭'}</h1>${!child?`<section class="up-family-code-card"><div><small>家庭码</small><b>${e(FAMILY_CODE||'尚未设置')}</b><p>家长和孩子使用同一个家庭码。通常只需在家庭设置时修改。</p></div>${button(FAMILY_CODE?'修改家庭码':'设置家庭码','family-code','up-secondary')}</section>`:''}<div class="up-profile">${buddy(d)}<div><div class="up-profile-name"><h2>${e(d.kidName||'小岛主')}</h2>${button('编辑','profile','up-link','aria-label="编辑孩子姓名"')}</div><p>${e(d.kidMood||'一起把每一天，过成喜欢的样子。')}</p></div></div>${[['report','每周与每月回顾','日周月统计、学科与完成记录'],['reward','奖励与积分管理','自定义伙伴、家庭心愿、兑现和加扣分'],['achieve','收藏与成长足迹','以前收集的每一件宝贝都在'],['settings','资料与旧版设置','姓名、历史统计与原有管理能力'],['cloud','家庭云端数据','家长与孩子在不同设备共享记录']].map(([a,n,s])=>`<button class="up-row" data-up="${a}"><span class="up-row-main"><b>${n}</b><small>${s}</small></span><span class="up-chevron">›</span></button>`).join('')}`;}
function cloudPage(d){return `<div class="up-eyebrow">家庭空间</div><h1>家庭云端数据</h1><div class="up-project"><h2>当前尚未连接云端数据库</h2><p>这个 GitHub Pages 版本目前只托管网页，家庭记录仍保存在当前设备。要实现家长端、儿童端和不同设备实时共享，需要先关联云端数据库并启用家庭成员权限。</p><dl class="up-data-stats"><dt>当前家庭码</dt><dd>${e(FAMILY_CODE||'未设置')}</dd><dt>同步状态</dt><dd>尚未连接</dd></dl></div><div class="up-notice">家庭码用于区分家庭数据；云端接入后还需配置成员访问权限，避免仅凭可猜测的家庭码读取孩子记录。</div>`;}
function dataPage(d){return `<div class="up-eyebrow">隔离体验 · 不连接线上家庭数据库</div><h1>数据与本机体验</h1><div class="up-project"><h2>可以带着旧数据来看看</h2><p>选择老版导出的 JSON 备份，保留作业、积分、伙伴、收藏、课表和附件；只替换这个 Demo 的本机数据。原服务和原备份不会改变。</p><label class="up-file-label">选择旧版备份<input type="file" id="up-import" accept="application/json,.json"></label>${button('导出当前 Demo 数据','export','up-secondary')}</div><div class="up-notice">此 Demo 的跨标签页更新只发生在当前浏览器。线上家庭同步、云端 AI 和正式发布未接入；图片识别使用浏览器本地 OCR，需要下载识别资源。</div>${section('当前数据')}<dl class="up-data-stats"><dt>作业</dt><dd>${d.homework.length} 条</dd><dt>周期模板</dt><dd>${(d.recurringTasks||[]).length} 个</dd><dt>课程／日程</dt><dd>${(d.classes||[]).length} / ${(d.events||[]).length}</dd><dt>已有积分</dt><dd>${d.points}</dd><dt>归档记录</dt><dd>${d.demoGrowth.archives.length} 条</dd></dl>${button('归档 30 天前已完成作业','archive','up-secondary')}${button('查看归档记录','archives','up-secondary')}${button('恢复演示样例（只影响本机 Demo）','reset-demo','up-danger')}`;}
function modal(content,cls=''){document.getElementById('up-dialog')?.remove();const d=document.createElement('dialog');d.id='up-dialog';d.className='up-dialog '+cls;d.innerHTML=`<div class="up-dialog-header">${button('关闭','close','up-close','aria-label="关闭弹层"')}</div><div class="up-dialog-body">${content}</div>`;document.body.append(d);d.showModal();d.addEventListener('click',ev=>{if(ev.target===d)d.close();});d.addEventListener('close',()=>d.remove());return d;}
function taskDetail(id){let d=data(),h=d.homework.find(x=>x.id===id);if(!h)return;ui.active=id;const r=d.demoGrowth.receipts['homework|'+id],b=companion(d);modal(`<div class="up-eyebrow">${e(h.subject)} · ${h.done?'已完成':h.pendingApproval?'已提交':'今日任务'}</div><h1>${e(h.content)}</h1><div class="up-writing-buddy">${buddy(d)}<div><h2>${e(b.name)}陪你写作业</h2><p>${e(b.line)}</p>${child?button('更换陪写伙伴','mate-picker','up-link',`data-task="${attr(id)}"`):''}</div></div><dl class="up-data-stats"><dt>预计时间</dt><dd>${h.duration||20} 分钟</dd><dt>完成积分</dt><dd>${r?.points??earnedPreview(d,h)}（含连击加分）</dd><dt>建设收获</dt><dd>${r?'本任务已记账':'首次完成 +10 建设力'}</dd></dl>${attachmentsHtml(h.attachments)}${h.pendingApproval?(child?'<div class="up-notice">已经提交给家长，确认后奖励一起到账。</div>':`${button('确认完成并结算奖励','approve','up-primary',`data-id="${attr(id)}"`)}${button('请孩子再补充一下','revise','up-secondary',`data-id="${attr(id)}"`)}`):h.done?`${button('看看完成记录','receipt','up-primary',`data-id="${attr(id)}"`)}${button('撤销完成','undo','up-secondary',`data-id="${attr(id)}"`)}`:`${button(child?'我完成了':'协助标记完成','complete','up-primary',`data-id="${attr(id)}"`)}${!child?`<label class="up-review-toggle"><input type="checkbox" id="up-review-toggle" data-id="${attr(id)}" ${h.requireReview?'checked':''}>本任务需要家长确认</label>`:''}`}${!child?`${button('编辑作业','edit-task','up-secondary',`data-id="${attr(id)}"`)}${button('删除作业','delete-task','up-danger',`data-id="${attr(id)}"`)}`:''}`);}
function receiptActions(d){
 if(!child)return button('返回今天','today','up-primary');
 const progress=DemoCore.homeworkProgress(d);
 if(!progress.complete)return `${button(progress.next?'继续下一个':'返回今天',progress.next?'continue-homework':'today','up-primary')}<p class="up-center up-muted">${progress.next?`今天还有 ${progress.remaining} 份作业，全部完成后就能建设小岛、布置房间。`:'作业已提交，等家长确认后，就能建设小岛、布置房间。'}</p>`;
 return `<p class="up-center up-muted">今日作业全部完成，去看看努力带来的变化吧。</p>${button('去建设我的小岛','island','up-primary')}${button('把收藏摆进房间','room','up-secondary')}${button('回到今天','today','up-link')}`;
}
function continueHomework(){const progress=DemoCore.homeworkProgress(data());navigate('today');if(progress.next)taskDetail(progress.next.id);else if(!progress.complete)showToast('作业已提交，等家长确认后再建设和布置。');}
function showReceipt(r,h){if(!r){modal(`<h1>这份努力已经留下了。</h1><p>这是升级前已完成的任务，原有积分和收藏已继承，不会重复发放。</p>${receiptActions(data())}`);return;}const d=data(),b=companion(d);modal(`<div class="up-celebrate">${buddy(d)}<span class="up-spark s1">✦</span><span class="up-spark s2">✧</span><span class="up-spark s3">${b.emoji==='🐶'?'♫':'✦'}</span></div><div class="up-eyebrow up-center">${e(b.name)}的完成时刻</div><h1 class="up-center">${r.replayed?'这份努力，我们记得。':'又完成了一件，真好。'}</h1><p class="up-center up-muted">${e(r.title||h?.content||'')}</p><div class="up-loot"><div><span>作业积分</span><b>+${r.points||0}</b></div><div><span>小岛建设力</span><b>${r.replayed?'已经记账':r.construction?'+'+r.construction:'本次不增加'}</b></div>${r.drops?.length?`<section><small>${r.replayed?'上次发现的宝贝，仍然保留着':'这次还发现了'}</small><div class="up-loot-items">${r.drops.map(id=>`<span>${materialArt(id)}<small>${e(MATERIALS.find(m=>m.id===id)?.name||id)}</small></span>`).join('')}</div></section>`:''}</div>${receiptActions(d)}`,'up-success');}
function legacy(view){document.querySelectorAll('.up-legacy-back').forEach(x=>x.remove());ui.legacy=view;root.classList.remove('on');document.querySelectorAll('.view').forEach(v=>v.classList.remove('on'));const target=document.querySelector(`.view[data-view="${view}"]`);if(target)target.classList.add('on');if(child){if(view==='calendar'){renderChildMonth();renderChildCalendarDay();}if(view==='report')renderChildReportPage(data());if(view==='achieve')renderChildAchieve(data());if(view==='shop')renderShop(data());}else{if(view==='report')renderParentReport(data());if(view==='review')renderParentReview(data());if(view==='reward')renderParentReward(data());if(view==='settings')renderParentSettings(data());if(view==='classes')renderParentClasses(data());if(view==='home')renderParent();}const up=document.createElement('div');up.className='up-legacy-back';up.append(Object.assign(document.createElement('button'),{textContent:'‹ 返回新版',onclick:()=>navigate(child?'island':'family')}));target?.prepend(up);paintChrome();}
function paintChrome(){if(!ready)return;let d=data(),route=ui.route;header.querySelector('.up-header-points').textContent=d.points+' 积分';nav.innerHTML=(child?[['today','今天','clipboard'],['plan','计划','backpack'],['island','我的小岛','house']]:[['today','今天','clipboard'],['plan','安排','backpack'],['family','家庭','house']]).map(([r,n,im])=>button(image(im)+`<span>${n}</span>`,r,'up-nav-item',`aria-current="${r===route||r==='today'&&route==='journal'||r==='island'&&['mates','room'].includes(route)?'page':'false'}"`)).join('');}
function render(){if(!ready)return;const d=data();if(!DemoCore.homeworkProgress(d).complete)ui.roomEdit=false;paintChrome();if(ui.legacy)return;document.querySelectorAll('.view').forEach(v=>v.classList.remove('on'));root.classList.add('on');const pages={today,plan,island,mates,room,family,journal,cloud:cloudPage};root.innerHTML=(pages[ui.route]||today)(d);}
function navigate(route){document.getElementById('up-dialog')?.close();ui.legacy=null;ui.route=route;if(route==='today')ui.date=todayStr();render();window.scrollTo({top:0,behavior:'instant'});}
function after(){if(!ready)return;try{child?renderChild():renderParent();}catch(err){console.warn(err);}if(ui.legacy){const old=ui.legacy;document.querySelectorAll('.up-legacy-back').forEach(x=>x.remove());legacy(old);}else render();}
// Keep exported editing and reporting functions, replacing only settlement and navigation.
completeHomework=function(id){const d=data(),h=d.homework.find(x=>x.id===id);if(!h||h.done)return;if(child&&h.requireReview){if(!h.pendingApproval){h.pendingApproval=true;saveData(d);}after();taskDetail(id);return;}const wasPending=h.pendingApproval;const r=DemoCore.finish(d,id);if(!child&&wasPending)h.rewardUnseen=true;saveData(d);after();showReceipt(r,h);};
undoHomework=function(id){const d=data();if(DemoCore.undo(d,id)){saveData(d);after();showToast('已撤销完成，原掉落与建设记录保留，不会重复发放。');}};
checkinClass=function(id,day){const d=data(),ds=typeof day==='string'?day:ui.date;const current=classCheckin(d,id,ds);if(current?.done){DemoCore.undo(d,id,'class',ds);saveData(d);after();showToast('已撤销课程打卡');return false;}const r=DemoCore.finish(d,id,'class',ds);saveData(d);after();showReceipt(r);return true;};
refreshAfterChange=after;
const originalRedeem=doRedeem;
doRedeem=function(id){const d=data(),i=(d.rewardItems||[]).find(x=>x.id===id);if(!i||i.active===false)return;if(i.type==='mate'&&(d.rewardsUnlocked||[]).includes(i.emoji)){showToast('这个伙伴已经拥有了');return;}if(!i.repeatable&&(d.redemptions||[]).some(r=>r.itemId===id)){showToast('这个奖励已经兑换过了');return;}originalRedeem(id);if(i.type==='mate'&&data().rewardsUnlocked.includes(i.emoji)){showToast(i.name+'已经上岛，可以请它来陪你了。');if(ui.redeemFromPicker){ui.redeemFromPicker=false;matePicker(ui.mateReturnTask);}}};
const originalRedeemPrompt=redeemReward;
redeemReward=function(id){originalRedeemPrompt(id);const item=data().rewardItems.find(x=>x.id===id),c=cast[item?.emoji],host=document.querySelector('#confirm-sheet .confirm-emo');if(item?.type==='mate'&&c&&host)host.innerHTML=`<img src="${c[3]}" alt="${e(item.name)}">`;};
const originalSettings=renderParentSettings;
renderParentSettings=function(d){originalSettings(d);setText('set-code','本机 Demo');setText('set-code-sub','当前记录只保存在此浏览器');setText('set-sync-state','隔离体验 · 未连接线上家庭');document.querySelectorAll('[data-view="settings"] [onclick]').forEach(b=>{if(/openSyncPanel|copyInviteLink/.test(b.getAttribute('onclick')||'')){b.setAttribute('aria-disabled','true');b.onclick=()=>showToast('本机 Demo 不建立线上家庭连接。');}});};
cleanDoneHomework=function(){const d=data(),cut=Date.now()-30*86400000,old=d.homework.filter(h=>h.done&&h.completedAt&&new Date(h.completedAt).getTime()<cut);if(!old.length){showToast('暂时没有需要归档的旧记录');return;}let ids=new Set(old.map(x=>x.id));d.demoGrowth.archives.push(...old.filter(h=>!d.demoGrowth.archives.some(x=>x.id===h.id)));d.homework=d.homework.filter(h=>!ids.has(h.id));saveData(d);after();showToast('旧记录已归档，积分、伙伴和收藏保留。');};
openMatePicker=function(){if(ready)matePicker();};
gotoChildView=function(view){if(!ready)return;if(view==='home')navigate('today');else if(view==='calendar')navigate('plan');else if(view==='mates')navigate('mates');else legacy(view);};
gotoParentView=function(view){if(!ready)return;if(view==='home')navigate('today');else if(view==='classes')legacy('classes');else legacy(view);};
window.addEventListener('storage',ev=>{if(ev.key===DEMO_KEY){generateRecurringTasks();after();}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-up]');if(!b)return;const a=b.dataset.up,id=b.dataset.id;const d=data();
 if(a==='mate-picker'){matePicker(b.dataset.task||null);return;}
 if(a==='continue-homework'){continueHomework();return;}
 if(child&&['build','room-edit','room-slot','room-action','room-zone','remove','item'].includes(a)&&!DemoCore.homeworkProgress(d).complete){ui.roomEdit=false;showToast('先完成今日作业，再建设小岛或布置房间。');continueHomework();return;}
 if(a==='journal-edit'){journalEditor(b.dataset.date||todayStr());return;}
 if(a==='journal-mood'){const draft=ui.journalDraft;if(!draft)return;draft.text=document.getElementById('up-journal-text').value;draft.mood=draft.mood===b.dataset.mood?'':b.dataset.mood;journalEditor(draft.day,draft);return;}
 if(a==='journal-save'){const draft=ui.journalDraft;if(!draft)return;draft.text=document.getElementById('up-journal-text').value;try{DemoCore.saveJournal(d,{day:draft.day,mood:draft.mood,text:draft.text});saveData(d);ui.journalDraft=null;document.getElementById('up-dialog')?.close();render();showToast('这段小记录，已经好好保存了。');}catch(err){document.getElementById('up-journal-error').textContent=err.message;}return;}
 if(['today','plan','island','mates','room','family','data','journal'].includes(a)){navigate(a);return;}
 if(a==='achieve'&&!child){modal('<h1>收藏与成长足迹</h1><p class="up-muted">以前收集到的宝贝，都还在这里。</p><div class="display-wall" id="up-parent-collection"></div>');renderMaterialWall(document.getElementById('up-parent-collection'),d,{hideEmpty:true});return;}
 if(['report','achieve','shop','reward','settings','classes','review'].includes(a)){document.getElementById('up-dialog')?.close();legacy(a);return;}
 if(a==='close'){document.getElementById('up-dialog')?.close();return;}
 if(a==='task'){taskDetail(id);return;}
 if(a==='complete'||a==='approve'){completeHomework(id);return;}
 if(a==='revise'){let h=d.homework.find(x=>x.id===id);if(h){h.pendingApproval=false;saveData(d);after();taskDetail(id);}return;}
 if(a==='undo'){undoHomework(id);document.getElementById('up-dialog')?.close();return;}
 if(a==='receipt'){let h=d.homework.find(x=>x.id===id);if(h){h.rewardUnseen=false;saveData(d);showReceipt(d.demoGrowth.receipts['homework|'+id],h);}return;}
 if(a==='class'){const c=d.classes.find(x=>x.id===id);if(c){modal(`<div class="up-eyebrow">课程与准备</div><h1>${e(c.name)}</h1><div id="up-course-content"></div>${!child?button('编辑课程','edit-class','up-secondary',`data-id="${attr(id)}"`):''}`);const it=dayItems(d).find(x=>x.kind==='class'&&x.id===id)||{cls:c,date:ui.date,checkin:classCheckin(d,id,ui.date),done:!!classCheckin(d,id,ui.date)?.done};document.getElementById('up-course-content').innerHTML=renderTlClass({...it,date:ui.date},mode);}return;}
 if(a==='event'){const v=d.events.find(x=>x.id===id);if(v){modal(`<div class="up-eyebrow">${v.owner==='child'?'自己安排的':'家长安排'}</div><h1>${e(v.title)}</h1><div id="up-event-content"></div>${button('编辑日程','edit-event','up-secondary',`data-id="${attr(id)}"`)}`);document.getElementById('up-event-content').innerHTML=renderTlEvent({ev:v,date:ui.date,done:v.done},mode);}return;}
 if(a==='family-code'){window.openFamilyCodeDialog?.();return;}
 if(a==='save-kid-name'){const name=(document.getElementById('up-kid-name')?.value||'').trim();if(!name){showToast('请填写孩子姓名');return;}d.kidName=name.slice(0,12);saveData(d);document.getElementById('up-dialog')?.close();after();showToast('孩子姓名已更新');return;}if(['publish','ocr','edit-task','delete-task','edit-class','edit-event','profile'].includes(a)){document.getElementById('up-dialog')?.close();if(a==='publish'||a==='ocr')openPublishSheet(a==='ocr'?'ocr':'manual');if(a==='edit-task')openHomeworkEditor(id);if(a==='delete-task')deleteHomework(id);if(a==='edit-class')openClassEditor(id);if(a==='edit-event')openEventEditor(id);if(a==='profile'){if(child)openMeEditor();else openKidNameEditor(d);return;}return;}
 if(a==='add-menu'){if(child){openEventEditor(null);$('ev-datetime').value=ui.date+'T17:30';}else modal(`<h1>想安排什么？</h1>${button('发布作业','publish','up-primary')}${button('识别截图或粘贴文字','ocr','up-secondary')}${button('每周固定课程','new-class','up-secondary')}${button('一次性自由日程','new-event','up-secondary')}`);return;}
 if(a==='new-class'||a==='new-event'){document.getElementById('up-dialog')?.close();if(a==='new-class')openClassEditor(null);else{openEventEditor(null);$('ev-datetime').value=ui.date+'T17:30';}return;}
 if(a==='recurring'){legacy('home');setTimeout(()=>$('p-recur-list')?.scrollIntoView({behavior:'smooth',block:'center'}),80);return;}
 if(a==='day'){ui.date=b.dataset.date;render();return;}if(a==='reset-day'){ui.date=todayStr();render();return;}if(a==='range'){ui.range=ui.range==='week'?'month':'week';render();return;}if(a==='filter'){ui.planType=b.dataset.filter;render();return;}
 if(a==='prev'||a==='next'){let x=new Date(ui.date+'T12:00:00');if(ui.range==='month')x.setMonth(x.getMonth()+(a==='next'?1:-1),1);else x.setDate(x.getDate()+(a==='next'?7:-7));ui.date=dateStr(x);render();return;}
 if(a==='project'){ui.project=b.dataset.project;render();return;}if(a==='next-project'){ui.project=nextProject(d)?.id||'garden';render();return;}
 if(a==='build'){const p=nextProject(d);if(!p||p.id!==b.dataset.project||d.demoGrowth.construction<p.cost)return;d.demoGrowth.construction-=p.cost;d.demoGrowth.buildings.push(p.id);saveData(d);render();modal(`<div class="up-build-celebrate">${image('sprout')}</div><h1 class="up-center">${e(p.name)}，建好了！</h1><p class="up-muted up-center">每一份努力，都让小岛多了一点变化。</p><div class="up-build-preview">${scene(d)}</div>${button('回到我的小岛','island','up-primary')}`);return;}
 if(a==='choose-mate'){const m=d.rewardItems.find(x=>x.id===id);if(m&&d.rewardsUnlocked.includes(m.emoji)){const task=ui.mateReturnTask;pickMate(m.emoji,m.name);showToast(m.name+'会陪你完成今天的作业。');if(b.dataset.picker){if(task)taskDetail(task);else{document.getElementById('up-dialog')?.close();render();}}else render();}return;}
 if(a==='redeem'){ui.redeemFromPicker=!!b.dataset.picker;document.getElementById('up-dialog')?.close();redeemReward(id);return;}
 if(a==='room-edit'){ui.roomEdit=!ui.roomEdit;ui.roomFrom=null;ui.roomAction='place';render();return;}
 if(a==='room-zone'){ui.roomZone=b.dataset.zone;render();return;}
 if(a==='room-action'){ui.roomAction=b.dataset.action;ui.roomFrom=null;render();return;}
 if(a==='item'){ui.selectedItem=b.dataset.item;ui.roomAction='place';ui.roomFrom=null;render();return;}
 if(a==='room-slot'){if(!ui.roomEdit)return;const slot=b.dataset.slot;let result;if(ui.roomAction==='move'){if(!ui.roomFrom){if(!d.demoGrowth.room[slot]){showToast('先选择一件已经摆好的收藏。');return;}ui.roomFrom=slot;render();return;}result=DemoCore.editRoom(d,'move',slot,ui.roomFrom);ui.roomFrom=null;}else result=DemoCore.editRoom(d,ui.roomAction==='remove'?'remove':'place',slot,ui.selectedItem);if(result.ok){saveData(d);render();}showToast(result.message);return;}
 if(a==='fulfill'){fulfillRedemption(id);after();return;}if(a==='export'){exportData();return;}if(a==='archive'){cleanDoneHomework();return;}
 if(a==='archives'){modal(`<h1>归档记录</h1>${d.demoGrowth.archives.map(h=>`<div class="up-row"><span class="up-row-main"><b>${e(h.content)}</b><small>${e(h.subject)} · ${e((h.completedAt||'').slice(0,10))} · 已完成</small></span></div>`).join('')||'<p class="up-muted">暂时没有归档记录。</p>'}`);return;}
 if(a==='reset-demo'){modal(`<h1>恢复演示样例？</h1><p>只替换本机 Demo 数据。可以先导出当前备份，线上服务不会受到影响。</p>${button('先导出备份','export','up-secondary')}${button('确认恢复样例','confirm-reset','up-danger')}`);return;}if(a==='confirm-reset'){localStorage.setItem(DEMO_KEY,JSON.stringify(DemoCore.ensure(DemoCore.seed())));generateRecurringTasks();navigate('today');return;}
});
document.addEventListener('input',ev=>{if(ev.target.id==='up-journal-text'){ui.journalDraft.text=ev.target.value;document.getElementById('up-journal-count').textContent=ev.target.value.length;document.getElementById('up-journal-error').textContent='';}});
document.addEventListener('change',async ev=>{if(ev.target.id==='up-review-toggle'){const d=data(),h=d.homework.find(x=>x.id===ev.target.dataset.id);if(h){h.requireReview=ev.target.checked;saveData(d);}return;}if(ev.target.id==='up-import'){const f=ev.target.files?.[0];if(!f)return;try{const raw=JSON.parse(await f.text()),checked=DemoCore.validate(raw);modal(`<h1>导入旧版备份</h1><p>检测到 ${checked.homework.length} 条作业，${Number(checked.points)||0} 积分。仅替换本机 Demo，不连接线上家庭。</p>${button('确认导入','confirm-import','up-primary')}${button('取消','close','up-secondary')}`);document.querySelector('[data-up="confirm-import"]').addEventListener('click',()=>{DemoCore.importData(checked);generateRecurringTasks();navigate('today');showToast('已导入本机 Demo，旧资产已保留。');},{once:true});}catch(err){showToast('导入失败：'+err.message);}}});
document.addEventListener('DOMContentLoaded',()=>{
document.querySelector('.topbar').hidden=true;document.querySelector('.sky')?.remove();const phone=document.querySelector('.phone');header=document.createElement('header');header.className='up-chrome';header.innerHTML=`<a class="up-brand" href="index.html"><img src="assets/logo.svg" alt="作业岛"></a><span class="up-header-points"></span><a class="up-mode-switch" href="${child?'parent':'child'}.html?v=20261019a" aria-label="切换到${child?'家长':'孩子'}端">${child?'家长端':'孩子端'} ↗</a>`;phone.prepend(header);
root=document.createElement('section');root.id='upgrade-root';root.className='view on up-main';root.dataset.view='upgrade';document.querySelector('.stage').prepend(root);
nav=document.createElement('nav');nav.className='up-nav';nav.setAttribute('aria-label','主要页面');document.querySelector('.tabbar').replaceWith(nav);ready=true;
const view=new URLSearchParams(location.search).get('view');if(view&&['report','shop','achieve','review','reward','settings','classes'].includes(view))legacy(view);else if(view==='calendar')navigate('plan');else if(view==='mates')navigate('mates');else if(view==='publish'){navigate('today');openPublishSheet('manual');}else navigate('today');
});
})();
